@pytest.mark.parametrize(
    ("debug", "expect"),
    [
        ("", False),
        ("0", False),
        ("False", False),
        ("No", False),
        ("True", True),
    ],
)
def test_get_debug_flag(self, monkeypatch, debug, expect):
    monkeypatch.setenv("FLASK_DEBUG", debug)
    assert get_debug_flag() == expect
